def make_unit(page,ex,summary):
 def e(q,h,step,a,ref): return ex(q,h,step,a,ref)
 return ('Heildun með innsetningu',[
 page('Keðjureglan lesin aftur á bak','Tengja heildun samsettra falla við keðjuregluna.',r'''<p>Í einingu 1 fundum við stofnföll grunnfalla. Við vitum til dæmis að:</p>\[\int\cos x\,dx=\sin x+C.\]<p>En hvað ef innan í cosinus stendur x² og fyrir framan hann stendur 2x? Rifjum fyrst upp diffrun.</p><h2>Innra og ytra fall</h2><p>Í \(\sin(x^2)\) er innra fallið \(x^2\). Ytra fallið er sinus: við reiknum fyrst x² og tökum svo sinus af niðurstöðunni. Keðjureglan gefur:</p>\[\frac{d}{dx}\sin(x^2)=\cos(x^2)\cdot2x.\]<p>Við diffrum ytra fallið og margföldum með afleiðu innra fallsins. Við getum nú lesið niðurstöðuna aftur á bak:</p>\[\int2x\cos(x^2)\,dx=\sin(x^2)+C.\]<aside>Það er samspil innri stæðunnar og afleiðu hennar sem hjálpar. Við heildun leitum við að mynstri sem keðjureglan hefði getað búið til.</aside><h3>Sýnidæmi 3.1.1 — veldi af stæðu</h3><p>Finna á stofnfall \(2x(x^2+1)^3\). Innri stæðan er x²+1 og afleiða hennar 2x. Við prófum að hækka veldið úr 3 í 4 og deila með 4:</p>\[F(x)=\frac{(x^2+1)^4}{4}.\]<p>Athugum með keðjureglunni:</p>\[F'(x)=\frac14\cdot4(x^2+1)^3\cdot2x=2x(x^2+1)^3.\]<p>Því er heildið:</p>\[\int2x(x^2+1)^3\,dx=\frac{(x^2+1)^4}{4}+C.\]<p>Í næsta undirkafla kynnum við innsetningu: skipulega leið til að nýta þetta samband.</p>''',[
 e(r'Finndu innri stæðuna og afleiðu hennar í \(\sin(3x+1)\).','Hvað er reiknað áður en sinus er tekinn?','Innri stæðan er 3x+1.',r'Innri stæðan er \(3x+1\) og afleiða hennar 3.','#s1'),
 e(r'Reiknaðu \(\int3x^2e^{x^3}\,dx\).','Hvaða fall hefur þessa afleiðu samkvæmt keðjureglunni?',r'Diffraðu \(e^{x^3}\).',r'\(e^{x^3}+C\). Athugun: \((e^{x^3})\prime=3x^2e^{x^3}\).','#s1')]),
 page('Innsetning skref fyrir skref','Umrita heildi með nýrri breytu og fara aftur í upphaflegu breytuna.',r'''<p>Innsetning felst í að gefa innri stæðu nýtt nafn, yfirleitt u. Þá verður heildið oft að grunnheildi sem við þekkjum.</p><h3>Sýnidæmi 3.2.1 — sama mynstur, ný breyta</h3>\[\int2x(x^2+1)^3\,dx.\]<h2>1. Veljum nýja breytu</h2>\[u=x^2+1.\]<h2>2. Finnum afleiðuna</h2>\[\frac{du}{dx}=2x.\]<p>Í innsetningarreikningi skrifum við þetta á forminu:</p>\[du=2x\,dx.\]<aside>Táknunin du heldur utan um breytingu heildunarbreytunnar. Hér kemur du í stað <strong>alls þáttarins 2x dx</strong>. Við skiptum ekki eingöngu x²+1 út fyrir u og látum restina standa.</aside><h2>3. Umritum allt heildið</h2><p>Stæðan x²+1 verður u og 2x dx verður du:</p>\[\int2x(x^2+1)^3\,dx=\int u^3\,du.\]<h2>4. Heildum með tilliti til u</h2>\[\int u^3\,du=\frac{u^4}{4}+C.\]<h2>5. Setjum x-stæðuna aftur inn</h2>\[\frac{u^4}{4}+C=\frac{(x^2+1)^4}{4}+C.\]<p>Upphaflega heildið var í x og því skrifum við lokasvarið líka í x. Sannprófun með diffrun er sýnd í 3.1.</p><h2>Prófaðu að velja innsetningu</h2><div class="formula" id="substitution-practice"><p>Í heildinu \(\int2x\cos(x^2)\,dx\), hvaða par af u og du breytir heildinu í grunnheildi?</p><div class="activity-options"><button type="button" data-sub-choice="0">u = x², du = 2x dx</button><button type="button" data-sub-choice="1">u = x², du = dx</button><button type="button" data-sub-choice="2">u = 2x, du = 2 dx</button></div><p id="sub-feedback" class="activity-feedback" role="status"></p></div>''',[
 e(r'Reiknaðu \(\int2x(x^2+3)^4\,dx\).','Gefðu stæðunni í sviganum nýtt nafn.',r'\(u=x^2+3\). Þá er \(du=2x\,dx\) og heildið \(\int u^4\,du\).',r'\(\frac{(x^2+3)^5}{5}+C\). Diffrað fæst \((x^2+3)^4\cdot2x\).','#s2'),
 e(r'Reiknaðu \(\int\cos x\,e^{\sin x}\,dx\).','Skoðaðu stæðuna í veldisvísinum.',r'\(u=\sin x\). Þá er \(du=\cos x\,dx\).',r'\(e^{\sin x}+C\), því afleiðan er \(e^{\sin x}\cos x\).','#s2')]),
 page('Fastir stuðlar og ólík mynstur','Leiðrétta fasta stuðla við innsetningu.',r'''<p>Afleiða innri stæðunnar er ekki alltaf nákvæmlega til staðar. Stundum munar aðeins föstum stuðli. Þá getum við leiðrétt hann.</p><h3>Sýnidæmi 3.3.1 — vísisfall</h3>\[\int e^{3x}\,dx.\]<p>Veljum u=3x. Þá fæst:</p>\[du=3\,dx.\]\[dx=\frac13\,du.\]<p>Þess vegna verður heildið:</p>\[\int e^{3x}\,dx=\frac13\int e^u\,du=\frac13e^u+C=\frac13e^{3x}+C.\]<p>Athugun:</p>\[\left(\frac13e^{3x}\right)'=\frac13\cdot3e^{3x}=e^{3x}.\]<h3>Sýnidæmi 3.3.2 — rót</h3>\[\int x\sqrt{x^2+4}\,dx.\]<p>Veljum u=x²+4. Þá er:</p>\[du=2x\,dx.\]\[x\,dx=\frac12\,du.\]<p>Umritum rótina sem veldi og heildum:</p>\[\int x\sqrt{x^2+4}\,dx=\frac12\int u^{1/2}\,du=\frac13u^{3/2}+C=\frac13(x^2+4)^{3/2}+C.\]<p>Athugun:</p>\[\left(\frac13(x^2+4)^{3/2}\right)'=\frac13\cdot\frac32(x^2+4)^{1/2}\cdot2x=x\sqrt{x^2+4}.\]<h2>Þegar þátt vantar</h2><p>Í \(\int xe^{x^2}\,dx\) hjálpar u=x², því x dx er helmingur af du. Í \(\int e^{x^2}\,dx\) vantar hins vegar x-þáttinn. Við megum ekki bæta honum við með föstum stuðli. Ekki er gert ráð fyrir að leysa síðara heildið með aðferðum þessa áfanga.</p>''',[
 e(r'Reiknaðu \(\int\cos(5x)\,dx\).','Afleiða 5x er 5.',r'\(u=5x\), svo \(dx=du/5\).',r'\(\sin(5x)/5+C\). Athugun gefur \(5\cos(5x)/5=\cos(5x)\).','#s3'),
 e(r'Reiknaðu \(\int x(x^2+2)^3\,dx\).','Afleiða innri stæðunnar er 2x.',r'Heildið verður \(\frac12\int u^3\,du\).',r'\((x^2+2)^4/8+C\). Afleiðan er \(4(x^2+2)^3\cdot2x/8=x(x^2+2)^3\).','#s3'),
 e(r'Nemandi fær \(\int\sin(4x)\,dx=-\cos(4x)+C\). Leiðréttu svarið með diffrun.','Hvaða stuðull kemur frá keðjureglunni?',r'Afleiða tillögunnar er \(4\sin(4x)\).',r'Rétt svar er \(-\cos(4x)/4+C\).','#s3')]),
 page('Innsetning og logrinn','Heilda þegar teljari tengist afleiðu nefnara.',r'''<p>Í einingu 1 lærðum við:</p>\[\int\frac1x\,dx=\ln|x|+C.\]<p>Innsetning gefur sambærilegt mynstur þegar í nefnaranum stendur flóknari stæða.</p><h3>Sýnidæmi 3.4.1 — alltaf jákvæður nefnari</h3>\[\int\frac{2x}{x^2+1}\,dx.\]<p>Veljum u=x²+1, svo du=2x dx. Þá fæst:</p>\[\int\frac{2x}{x^2+1}\,dx=\int\frac1u\,du=\ln|u|+C=\ln(x^2+1)+C.\]<p>Þar sem x²+1 er alltaf jákvætt þarf ekki algildismerki í lokasvarinu. Athugun:</p>\[\bigl(\ln(x^2+1)\bigr)'=\frac{2x}{x^2+1}.\]<h3>Sýnidæmi 3.4.2 — nefnari getur verið neikvæður</h3>\[\int\frac1{2x-3}\,dx.\]<p>Veljum u=2x−3. Þá er du=2 dx og dx=du/2:</p>\[\int\frac1{2x-3}\,dx=\frac12\int\frac1u\,du=\frac12\ln|2x-3|+C.\]<p>Algildismerkin gera okkur kleift að nota formúluna bæði þegar 2x−3 er jákvætt og neikvætt. Heildisstofninn er óskilgreindur við x=3/2; stofnfallið er því skoðað á bili sem fer ekki yfir þann punkt. Athugun:</p>\[\left(\frac12\ln|2x-3|\right)'=\frac12\cdot\frac2{2x-3}=\frac1{2x-3}.\]<h2>Almenna mynstrið</h2>\[\int\frac{g'(x)}{g(x)}\,dx=\ln|g(x)|+C.\]<p>Hér er g diffranlegt og g(x)≠0 á bilinu sem við skoðum. Stundum þarf að leiðrétta fastan stuðul eins og í sýnidæminu hér að ofan.</p>''',[
 e(r'Reiknaðu \(\int\frac3{3x+1}\,dx\).','Berðu teljarann saman við afleiðu nefnarans.',r'\(u=3x+1\), svo \(du=3\,dx\).',r'\(\ln|3x+1|+C\), á bili sem inniheldur ekki −1/3.','#s4'),
 e(r'Reiknaðu \(\int\frac{x}{x^2+4}\,dx\).','Afleiða nefnarans er 2x.',r'Leiðréttu með stuðlinum 1/2.',r'\(\frac12\ln(x^2+4)+C\). Nefnarinn er alltaf jákvæður.','#s4')]),
 page('Innsetning í ákveðnum heildum','Breyta heildunarmörkum með nýrri breytu.',r'''<p>Í ákveðnu heildi fylgja mörkin heildunarbreytunni. Ef við breytum úr x í u þurfum við líka að reikna hvaða u-gildi samsvara endapunktunum.</p><h3>Sýnidæmi 3.5.1 — ný breyta, ný mörk</h3>\[\int_1^2\frac{2x}{x^2+1}\,dx.\]<p>Veljum u=x²+1. Þá er du=2x dx. Reiknum nýju mörkin:</p>\[x=1\ \Longrightarrow\ u=1^2+1=2.\]\[x=2\ \Longrightarrow\ u=2^2+1=5.\]<p>Nú er bæði heildisstofninn og mörkin skrifuð með u:</p>\[\int_1^2\frac{2x}{x^2+1}\,dx=\int_2^5\frac1u\,du=\left[\ln u\right]_2^5=\ln5-\ln2=\ln\frac52.\]<h2>Önnur leið: fara aftur í x</h2><p>Við getum líka fundið stofnfallið fyrst, sett x-stæðuna aftur inn og notað þá upphaflegu mörkin:</p>\[\left[\ln(x^2+1)\right]_1^2=\ln5-\ln2.\]<aside>Báðar leiðir gefa sama svar. Notaðu u-mörk með stofnfalli í u og x-mörk með stofnfalli í x. Ekki blanda þeim saman.</aside><h3>Sýnidæmi 3.5.2 — veldi</h3>\[\int_0^1 2x(x^2+1)^2\,dx.\]<p>Með u=x²+1 og du=2x dx verða neðri mörkin 1 og efri mörkin 2:</p>\[\int_1^2u^2\,du=\left[\frac{u^3}{3}\right]_1^2=\frac83-\frac13=\frac73.\]<p>Til athugunar má nota stofnfallið \((x^2+1)^3/3\) með upprunalegu mörkunum 0 og 1. Það gefur líka 7/3.</p>''',[
 e(r'Reiknaðu \(\int_0^2x(x^2+1)^2\,dx\).','Breyttu bæði stæðu og mörkum.',r'Heildið verður \(\frac12\int_1^5u^2\,du\).',r'\((125-1)/6=62/3\).','#s5'),
 e(r'Reiknaðu \(\int_0^{\pi/2}\sin x\cos x\,dx\).','Veldu u=sin x.',r'Mörkin verða 0 og 1; heildið er \(\int_0^1u\,du\).',r'\([u^2/2]_0^1=1/2\).','#s5')]),
 page('Samantekt, orðalisti og formúlur','Ná yfirsýn yfir innsetningu.',summary(['Innsetning nýtir keðjuregluna aftur á bak.','Veldu innri stæðu og finndu afleiðu hennar.','Umritað heildi á að vera í einni breytu.','Fasta stuðla má leiðrétta; breytilegum þáttum má ekki sleppa.','Í óákveðnu heildi ferðu aftur í upphaflegu breytuna.','Í ákveðnu heildi verða breyta og mörk að passa saman.'],[('<a href="#s2">Innsetning</a> <span lang="en">(substitution)</span>','Ný breyta kemur í stað stæðu til að einfalda heildi.'),('<a href="#s1">Innra fall</a> <span lang="en">(inner function)</span>','Fallið sem reiknað er áður en ytra fallið er tekið af niðurstöðunni.'),('<a href="#s2">du í innsetningu</a>','Táknun sem heldur utan um breytingu heildunarbreytunnar; ef u=g(x) er du=g′(x) dx.'),('<a href="#s5">Ný heildunarmörk</a>','Gildi nýju breytunnar sem samsvara upphaflegum endapunktum.')],r'<p><strong>Innsetning</strong></p>\[u=g(x).\]\[du=g\prime(x)\,dx.\]\[\int f(g(x))g\prime(x)\,dx=F(g(x))+C.\]<p>Hér er F′=f. Föllin þurfa að vera skilgreind á bilinu sem við skoðum og keðjureglan að gilda.</p><p><strong>Logramynstur með innsetningu</strong></p>\[\int\frac{g\prime(x)}{g(x)}\,dx=\ln|g(x)|+C.\]<p>Í logramynstrinu þarf g(x)≠0 á bilinu.</p>')+r'''<h2>Algeng mistök</h2><ul><li>Að breyta innri stæðu en gleyma að umrita dx og meðfylgjandi þætti.</li><li>Að missa fasta stuðulinn sem kemur frá afleiðu innri stæðunnar.</li><li>Að skila óákveðnu heildi í u þótt upphaflega heildið sé í x.</li><li>Að nota x-mörk með stofnfalli í u.</li></ul><h2>Athugaðu skilninginn</h2><ul><li>Geturðu útskýrt hvers vegna innsetning hjálpar í tilteknu heildi?</li><li>Geturðu fundið gleymdan stuðul með því að diffra lokasvarið?</li><li>Geturðu útskýrt hvernig ný heildunarmörk fást?</li></ul>''',[]),
 page('Blandað dæmasafn','Velja milli grunnreglna, einföldunar og innsetningar.','',[
 e(r'Reiknaðu \(\int(3x+2)^4\,dx\).','Skoðaðu innri stæðuna.',r'\(u=3x+2\), svo \(dx=du/3\).',r'\((3x+2)^5/15+C\).','#s3'),
 e(r'Reiknaðu \(\int(x^2+2x+1)\,dx\).','Grunnreglurnar nægja hér.','Heilda hvern lið fyrir sig.',r'\(x^3/3+x^2+x+C\).','index.html#s5'),
 e(r'Reiknaðu \(\int\frac{x}{x^2+9}\,dx\).','Berðu nefnarann saman við teljarann.',r'\(u=x^2+9\). Þá er \(x\,dx=du/2\).',r'\(\frac12\ln(x^2+9)+C\).','#s4'),
 e(r'Reiknaðu \(\int_0^1 3x^2(x^3+1)^2\,dx\).','Skoðaðu stæðuna í sviganum og breyttu mörkum.',r'Heildið verður \(\int_1^2u^2\,du\).',r'\([u^3/3]_1^2=7/3\).','#s5'),
 e(r'Reiknaðu \(\int\frac{x^2+2x}{x}\,dx\), fyrir x>0.','Einfaldaðu brotið áður en þú velur leið.',r'Heildisstofninn er x+2.',r'\(x^2/2+2x+C\), fyrir x>0.','index.html#s5'),
 e(r'Reiknaðu \(\int e^{2x+1}\,dx\).','Afleiða stæðunnar í veldisvísinum er fasti.',r'\(u=2x+1\), svo \(dx=du/2\).',r'\(e^{2x+1}/2+C\).','#s3')])])
